import * as arc from "open-arc";

export type ParseFn = (phrase: string) => string;

export const parseSpec = arc.defineRegion<ParseFn>({
  "id": "acronym.parse",
  "intent": "Exercise \"acronym\": implement `parse`.\n\nConvert a phrase to its acronym.\n\nTechies love their TLA (Three Letter Acronyms)!\n\nHelp generate some jargon by writing a program that converts a long name like Portable Network Graphics to its acronym (PNG).\n\nPunctuation is handled as follows: hyphens are word separators (like whitespace); all other punctuation can be removed from the input.\n\nFor example:\n\n| Input                     | Output |\n| ------------------------- | ------ |\n| As Soon As Possible       | ASAP   |\n| Liquid-crystal display    | LCD    |\n| Thank George It's Friday! | TGIF   |",
  "examples": [
    {
      "name": "Acronym are produced from > title cased phrases",
      "args": [
        "Portable Network Graphics"
      ],
      "expected": "PNG"
    },
    {
      "name": "Acronym are produced from > other title cased phrases",
      "args": [
        "Ruby on Rails"
      ],
      "expected": "ROR"
    },
    {
      "name": "Acronym are produced from > inconsistently cased phrases",
      "args": [
        "HyperText Markup Language"
      ],
      "expected": "HTML"
    }
  ]
});

// @openarc:begin acronym.parse
export const parse: ParseFn = (phrase) => arc.todo("acronym.parse");
// @openarc:end acronym.parse

export function parse(phrase: string): string {
  if (!phrase) return "";

  // Replace hyphens with spaces to treat them as word separators
  const normalized = phrase.replace(/-/g, " ");

  // Split by whitespace, filter out empty strings, and take the first letter of each word
  const acronym = normalized
    .split(/\s+/)
    .filter((word) => word.length > 0)
    .map((word) => word[0].toUpperCase())
    .join("");

  return acronym;
}

