import * as arc from "open-arc";

export type CountFn = (rows: string[]) => number;

export const countSpec = arc.defineRegion<CountFn>({
  "id": "rectangles.count",
  "intent": "Exercise \"rectangles\": implement `count`.\n\nCount the rectangles in an ASCII diagram like the one below.\n\n```text\n   +--+\n  ++  |\n+-++--+\n|  |  |\n+--+--+\n```\n\nThe above diagram contains these 6 rectangles:\n\n```text\n\n+-----+\n|     |\n+-----+\n```\n\n```text\n   +--+\n   |  |\n   |  |\n   |  |\n   +--+\n```\n\n```text\n   +--+\n   |  |\n   +--+\n\n```\n\n```text\n\n   +--+\n   |  |\n   +--+\n```\n\n```text\n\n+--+\n|  |\n+--+\n```\n\n```text\n\n  ++\n  ++\n\n```\n\nYou may assume that the input is always a proper rectangle (i.e. the length of every line equals the length of the first line).",
  "examples": [
    {
      "name": "Rectangles > no rows",
      "args": [
        []
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no columns",
      "args": [
        [
          ""
        ]
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no rectangles",
      "args": [
        [
          " "
        ]
      ],
      "expected": 0
    }
  ]
});

// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  const H = rows.length;
  if (H === 0) return 0;
  const W = rows[0].length;
  if (W === 0) return 0;
  const isCorner = (r: number, c: number): boolean => {
      if (r < 0 || r >= H || c < 0 || c >= W) return false;
      return rows[r][c] === '+';
    };
  const isHorizontalEdge = (r: number, c: number): boolean => {
      if (r < 0 || r >= H || c < 0 || c >= W) return false;
      return rows[r][c] === '+' || rows[r][c] === '-';
    };
  const isVerticalEdge = (r: number, c: number): boolean => {
      if (r < 0 || r >= H || c < 0 || c >= W) return false;
      return rows[r][c] === '+' || rows[r][c] === '|';
    };
  let count = 0;
  for (let r1 = 0; r1 < H; r1++) {
      for (let c1 = 0; c1 < W; c1++) {
        if (!isCorner(r1, c1)) continue;

        for (let r2 = r1 + 1; r2 < H; r2++) {
          for (let c2 = c1 + 1; c2 < W; c2++) {
            if (!isCorner(r1, c2)) continue;
            if (!isCorner(r2, c1)) continue;
            if (!isCorner(r2, c2)) continue;

            let valid = true;
            for (let c = c1 + 1; c < c2; c++) {
              if (!isHorizontalEdge(r1, c)) { valid = false; break; }
              if (!isHorizontalEdge(r2, c)) { valid = false; break; }
            }
            if (!valid) continue;

            for (let r = r1 + 1; r < r2; r++) {
              if (!isVerticalEdge(r, c1)) { valid = false; break; }
              if (!isVerticalEdge(r, c2)) { valid = false; break; }
            }
            if (!valid) continue;

            count++;
          }
        }
      }
    }
  return count;
};
// @openarc:end rectangles.count

export function count(rows: string[]): number {
  if (!rows || rows.length === 0) return 0;

  const numCols = rows[0].length;
  if (numCols === 0) return 0;

  // Validate that all rows have the same length as the first row
  for (const row of rows) {
    if (row.length !== numCols) {
      throw new Error("All rows must have the same length");
    }
  }

  const numRows = rows.length;
  let rectangleCount = 0;

  // Iterate over all possible top-left corners (r1, c1)
  for (let r1 = 0; r1 < numRows; r1++) {
    for (let c1 = 0; c1 < numCols; c1++) {
      // Top-left corner must be '+'
      if (rows[r1][c1] !== '+') continue;

      // Iterate over all possible bottom-right corners (r2, c2)
      for (let r2 = r1 + 1; r2 < numRows; r2++) {
        for (let c2 = c1 + 1; c2 < numCols; c2++) {
          // Bottom-right corner must be '+'
          if (rows[r2][c2] !== '+') continue;

          // Check the other two corners
          if (rows[r1][c2] !== '+' || rows[r2][c1] !== '+') continue;

          // Check the top edge
          let topEdgeValid = true;
          for (let c = c1 + 1; c < c2; c++) {
            if (rows[r1][c] !== '-') {
              topEdgeValid = false;
              break;
            }
          }
          if (!topEdgeValid) continue;

          // Check the bottom edge
          let bottomEdgeValid = true;
          for (let c = c1 + 1; c < c2; c++) {
            if (rows[r2][c] !== '-') {
              bottomEdgeValid = false;
              break;
            }
          }
          if (!bottomEdgeValid) continue;

          // Check the left edge
          let leftEdgeValid = true;
          for (let r = r1 + 1; r < r2; r++) {
            if (rows[r][c1] !== '|') {
              leftEdgeValid = false;
              break;
            }
          }
          if (!leftEdgeValid) continue;

          // Check the right edge
          let rightEdgeValid = true;
          for (let r = r1 + 1; r < r2; r++) {
            if (rows[r][c2] !== '|') {
              rightEdgeValid = false;
              break;
            }
          }
          if (!rightEdgeValid) continue;

          // If all checks pass, we found a rectangle
          rectangleCount++;
        }
      }
    }
  }

  return rectangleCount;
}

