export function parse(phrase: string): string {
  if (!phrase) return "";

  // Replace hyphens with spaces to treat them as word separators
  const normalized = phrase.replace(/-/g, " ");

  // Split by whitespace, filter out empty strings, and take the first letter of each word
  const acronym = normalized
    .split(/\s+/)
    .filter((word) => word.length > 0)
    .map((word) => word[0].toUpperCase())
    .join("");

  return acronym;
}

