      // Rule 1 check inside loop? No, Rule 1 is handled before.
      // But wait, if word is "xr...", Rule 1 catches it.
      // If word is "yt...", Rule 1 catches it.

      // Check for 'y' acting as vowel
      if (char === 'y') {
        // If 'y' is at start, it's a vowel (Rule 1 implicit or standard behavior)
        // If 'y' is after consonants, it's the vowel (Rule 4)
        splitIndex++;
        break;
      }

      if (vowels.has(char)) {
        splitIndex++;
        break;
      }

      // Consonant
      splitIndex++;
    }

    // Edge case: if loop finished without break (e.g. "rhythm" breaks at y, "gym" breaks at y)
    // What if word is "rthm"? (No vowels, no y). 
    // Loop runs to end. splitIndex = len.
    // Result: "" + "rthm" + "ay" -> "rthmay". Correct.

    return word.slice(splitIndex) + word.slice(0, splitIndex) + 'ay';
