        lines.push('and ' + gifts[i - 1]);
      } else {
        lines.push(gifts[i - 1]);
      }
    }
    return 'On the ' + days[n - 1] + ' day of Christmas my true love gave to me: ' + lines.join(', ') + '.\n';
