      return word + 'ay';
    }
    let i = 0;
    while (i < word.length) {
      const char = word[i];
      if (char === 'y' && i > 0) {
        break;
      }
      if (vowels.has(char) && char !== 'u') {
        if (word[i + 1] === 'u') {
          i++;
        }
        break;
