// @openarc:begin spiralMatrix.ofSize
export const ofSize: OfSizeFn = (size) => {
  const n = size;
  const matrix = Array.from({ length: n }, () => Array(n).fill(0));
  let num = 1;
  let top = 0, bottom = n - 1, left = 0, right = n - 1;
  while (top <= bottom && left <= right) {
    for (let i = left; i <= right; i++) matrix[top][i] = num++;
    top++;
    for (let i = top; i <= bottom; i++) matrix[i][right] = num++;
    right--;
    if (top <= bottom) {
      for (let i = right; i >= left; i--) matrix[bottom][i] = num++;
      bottom--;
    }
    if (left <= right) {
      for (let i = bottom; i >= top; i--) matrix[i][left] = num++;
      left++;
    }
  }
  return matrix;
};
// @openarc:end spiralMatrix.ofSize

export function ofSize(size: number): number[][] {
  if (size === 0) {
    return [];
  }

  const matrix: number[][] = Array.from({ length: size }, () => Array(size).fill(0));

  let top = 0;
  let bottom = size - 1;
  let left = 0;
  let right = size - 1;
  let num = 1;
  const target = size * size;

  while (num <= target) {
    // Traverse from left to right along the top row
    for (let col = left; col <= right && num <= target; col++) {
      matrix[top][col] = num++;
    }
    top++;

    // Traverse from top to bottom along the right column
    for (let row = top; row <= bottom && num <= target; row++) {
      matrix[row][right] = num++;
    }
    right--;

    // Traverse from right to left along the bottom row
    for (let col = right; col >= left && num <= target; col--) {
      matrix[bottom][col] = num++;
    }
    bottom--;

    // Traverse from bottom to top along the left column
    for (let row = bottom; row >= top && num <= target; row--) {
      matrix[row][left] = num++;
    }
    left++;
  }

  return matrix;
}

