export const sum: SumFn = (factors, limit) => {
  const seen = new Set<number>();
  for (const factor of factors) {
    if (factor === 0) continue;
    for (let multiple = factor; multiple < limit; multiple += factor) {
      seen.add(multiple);
    }
  }
  let sum = 0;
  for (const n of seen) {
    sum += n;
  }
  return sum;
};
// @openarc:end sumOfMultiples.sum

export function sum(factors: number[], limit: number): number {
  const multiples = new Set<number>();

  for (const factor of factors) {
    if (factor <= 0) continue;

    for (let multiple = factor; multiple < limit; multiple += factor) {
      multiples.add(multiple);
    }
  }

  return Array.from(multiples).reduce((acc, val) => acc + val, 0);
}

