export function transpose(rows: string[]): string[] {
  if (rows.length === 0) {
    return [];
  }

  // Determine the maximum length among all rows to know how many columns we need to generate
  const maxLen = Math.max(...rows.map((row) => row.length));

  const result: string[] = [];

  // Iterate over each column index (from 0 to maxLen - 1)
  for (let col = 0; col < maxLen; col++) {
    let newRow = "";

    // Iterate over each row to build the new column
    for (let rowIdx = 0; rowIdx < rows.length; rowIdx++) {
      const currentRow = rows[rowIdx];

      if (col < currentRow.length) {
        // Character exists in this row at this column index
        newRow += currentRow[col];
      } else {
        // Character does not exist; pad with space
        // However, we must not pad to the right of the last non-space character in the *output* row.
        // But the instruction says: "Pad to the left with spaces" for input rows of different lengths.
        // And: "if a column in the input text contains only spaces on its bottom-most row(s), 
        // the corresponding output row should contain the spaces in its right-most column(s)."
        //
        // Let's re-read carefully:
        // "Pad to the left with spaces." -> This refers to the INPUT rows being shorter than the max.
        // Example: 
        // ABC
        // DE
        // Transposed:
        // AD
        // BE
        // C
        //
        // Here, the second row "DE" is padded with a space to become "DE " conceptually before transposing?
        // No, the example shows:
        // Input:
        // ABC
        // DE
        // Output:
        // AD
        // BE
        // C
        //
        // Column 0: A, D -> "AD"
        // Column 1: B, E -> "BE"
        // Column 2: C, (missing) -> "C"
        //
        // Example 2:
        // AB
        // DEF
        // Output:
        // AD
        // BE
        //  F
        //
        // Column 0: A, D -> "AD"
        // Column 1: B, E -> "BE"
        // Column 2: (missing), F -> " F" (Space then F)
        //
        // So the rule is:
        // 1. If the current row is shorter than the column index, we treat it as a space for the purpose of alignment?
        //    Actually, looking at Example 2, Column 2 of Row 0 is missing. Column 2 of Row 1 is 'F'.
        //    The output row for Column 2 is " F". This means the missing character from Row 0 became a space.
        //    And the 'F' from Row 1 is placed.
        //
        // 2. The constraint "Don't pad to the right" applies to the INPUT rows.
        //    Meaning, if an input row is "AB", it doesn't have a trailing space.
        //    When transposing, if we are at a column index beyond the length of a row, we put a space.
        //
        // 3. The constraint "if a column in the input text contains only spaces on its bottom-most row(s), 
        //    the corresponding output row should contain the spaces in its right-most column(s)."
        //    This implies we should NOT trim trailing spaces from the generated output rows.
        //    We must preserve the spaces that were implicitly added due to shorter input rows.
        //
        // So the logic is simple:
        // For each column index `col`:
        //   For each row index `rowIdx`:
        //     If `col` < `rows[rowIdx].length`, append `rows[rowIdx][col]`.
        //     Else, append " ".
        //   Join these characters to form the new row.
        //   Add to result.
        //
        // Let's verify with Example 2:
        // rows = ["AB", "DEF"]
        // maxLen = 3
        // col = 0:
        //   row 0: "AB"[0] = 'A'
        //   row 1: "DEF"[0] = 'D'
        //   newRow = "AD"
        // col = 1:
        //   row 0: "AB"[1] = 'B'
        //   row 1: "DEF"[1] = 'E'
        //   newRow = "BE"
        // col = 2:
        //   row 0: "AB" length is 2, so col 2 is out of bounds -> " "
        //   row 1: "DEF"[2] = 'F'
        //   newRow = " F"
        // Result: ["AD", "BE", " F"] -> Matches example.
        //
        // Example 1:
        // rows = ["ABC", "DE"]
        // maxLen = 3
        // col = 0: 'A', 'D' -> "AD"
        // col = 1: 'B', 'E' -> "BE"
        // col = 2: 'C', (out of bounds) -> "C"
        // Result: ["AD", "BE", "C"] -> Matches example.

        newRow += " ";
      }
    }

    result.push(newRow);
  }

  return result;
}

