export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
    let accumulator = 0;
    let continuation = true;

    for (let i = 0; i < bytes.length; i++) {
      const byte = bytes[i];
      accumulator = (accumulator << 7) | (byte & 0x7f);
      continuation = (byte & 0x80) !== 0;

      if (!continuation) {
        result.push(accumulator);
        accumulator = 0;
      }
    }

    if (continuation) {
      throw new Error('Incomplete sequence');
    }

    return result;
};
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    const bytes: number[] = [];
    let n = num;

    while (n > 0) {
      const byte = n & 0x7F;
      n >>= 7;
      bytes.unshift(byte);
    }

    // Set continuation bit for all bytes except the last one
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80;
    }

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0;
  let bitsCollected = 0;

  for (const byte of bytes) {
    // Validate byte range
    if (byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    if ((byte & 0x80) === 0) {
      // Last byte of the sequence
      if (bitsCollected === 0) {
        // Single byte number (0-127)
        result.push(byte);
      } else {
        // Multi-byte number finished
        // Shift left by 7 for each previous byte and add current byte
        let value = 0;
        for (let i = 0; i < bitsCollected; i++) {
          value = (value << 7) | (currentNumber & 0x7F);
        }
        value = (value << 7) | byte;

        if (value > 0xFFFFFFFF) {
          throw new Error("Decoded number exceeds 32-bit unsigned integer range");
        }
        result.push(value);
      }
      bitsCollected = 0;
      currentNumber = 0;
    } else {
      // Not the last byte
      bitsCollected++;
      currentNumber = byte;
    }
  }

  // If we ended without finishing a number (continuation bit set on last byte)
  if (bitsCollected > 0) {
    throw new Error("Incomplete variable-length quantity");
  }

  return result;
}

export function answer(question: string): number {
  if (!question || typeof question !== "string") {
    throw new Error("Invalid question");
  }

  // Remove surrounding whitespace and the fixed prefix/suffix
  const trimmed = question.trim();
  if (!trimmed.startsWith("What is ")) {
    throw new Error("Unknown operation");
  }

  // Extract the expression part between "What is " and the final "?"
  const expression = trimmed.slice(8, -1).trim();
  if (!expression) {
    throw new Error("Syntax error");
  }

  // Tokenize the expression
  // We split by spaces, but we need to handle negative numbers correctly.
  // A simple regex split might break "-5" if not careful, but since we split by space,
  // "-5" will be a single token if there are no spaces around the minus sign.
  // However, "minus 5" becomes ["minus", "5"].
  // We need to distinguish between the operator word "minus" and a unary minus in a number.
  // The problem statement implies standard word problems like "5 plus -3" or "What is -5?".
  // Let's tokenize carefully.

  const tokens = expression.split(/\s+/);

  if (tokens.length === 0) {
    throw new Error("Syntax error");
  }

  // Helper to parse a number token
  const parseNumber = (token: string): number => {
    const num = Number(token);
    if (Number.isNaN(num)) {
      throw new Error("Syntax error");
    }
    return num;
  };

  // Helper to check if a token is a valid number
  const isNumber = (token: string): boolean => {
    const num = Number(token);
    return !Number.isNaN(num) && token.trim() !== "";
  };

  // Helper to check if a token is a known operator
  const isOperator = (token: string): boolean => {
    return ["plus", "minus", "multiplied", "divided"].includes(token);
  };

  // Helper to get the operator word from the operation type
  const getOperatorWord = (op: string): string => {
    switch (op) {
      case "+":
        return "plus";
      case "-":
        return "minus";
      case "*":
        return "multiplied";
      case "/":
        return "divided";
      default:
        return "";
    }
  };

  // We will process tokens sequentially.
  // The first token must be a number.
  let currentResult: number;
  let index = 0;

  // Parse the first number
  if (!isNumber(tokens[index])) {
    throw new Error("Syntax error");
  }
  currentResult = parseNumber(tokens[index]);
  index++;

  // Process remaining tokens
  while (index < tokens.length) {
    const token = tokens[index];

    // Check if it's an operator
    if (!isOperator(token)) {
      // If it's not an operator and not a number (which shouldn't happen if logic is correct),
      // or if it's a number but we expect an operator (e.g., "5 5"), it's an error.
      // Actually, if we see a number here, it means we missed an operator or have invalid syntax like "5 plus 5 5".
      // But strictly, after an operator, we expect a number.
      // If we encounter a number here, it implies "5 plus 5 5" -> after "5", we see "5" which is not an operator.
      throw new Error("Syntax error");
    }

    // Determine the operation
    let operation: string;
    let nextTokenIndex = index + 1;

    if (token === "plus") {
      operation = "+";
    } else if (token === "minus") {
      operation = "-";
    } else if (token === "multiplied") {
      operation = "*";
    } else if (token === "divided") {
      operation = "/";
    } else {
      throw new Error("Unknown operation");
    }

    // Check if there is a next token
    if (nextTokenIndex >= tokens.length) {
      throw new Error("Syntax error");
    }

    const nextToken = tokens[nextTokenIndex];

    // The next token must be a number
    if (!isNumber(nextToken)) {
      throw new Error("Syntax error");
    }

    const nextValue = parseNumber(nextToken);

    // Perform the operation
    switch (operation) {
      case "+":
        currentResult += nextValue;
        break;
      case "-":
        currentResult -= nextValue;
        break;
      case "*":
        currentResult *= nextValue;
        break;
      case "/":
        if (nextValue === 0) {
          throw new Error("Division by zero");
        }
        currentResult /= nextValue;
        break;
    }

    // Move to the next operator
    index = nextTokenIndex + 1;
  }

  // Return the result as an integer (truncating decimals if necessary, though math problems usually imply exact integers)
  // The prompt says "returning the answer as an integer".
  // In JS, division might result in floats. We should cast to int if the result is a whole number, 
  // or just return the number. Usually, these exercises expect the mathematical integer result.
  // If the result is 5.0, return 5. If 5.5, it's ambiguous, but inputs are integers and operations are standard.
  // Let's return the number. If it's a float from division (e.g. 5/2 = 2.5), the prompt examples don't show this.
  // However, "returning the answer as an integer" suggests we might need to cast.
  // Given "What is 25 divided by 5? 5", it's exact.
  // Let's assume the result is always an integer based on the problem type, but to be safe and compliant with "as an integer":
  return Math.round(currentResult);
}
